// Fade — PWM, not just on and off.
//
// Pin 6 is a PWM pin. analogWrite() switches it fast enough that the LED's
// brightness is the duty cycle: 25% is a quarter as bright, not flickering.

int brightness = 0;
int step = 5;

void setup() {
  pinMode(6, OUTPUT);
}

void loop() {
  analogWrite(6, brightness);
  brightness += step;
  if (brightness <= 0 || brightness >= 255) step = -step;
  delay(20);
}
